insert into public.vocabulary (word, ipa, definition_en, meaning_vi, example, collocations, week_number) values
('accommodation', '/əˌkɒməˈdeɪʃn/', 'a place to live or stay', 'chỗ ở', 'The price includes flights and accommodation.', array['student accommodation', 'book accommodation']::text[], 1),
('deposit', '/dɪˈpɒzɪt/', 'money paid in advance as security', 'tiền đặt cọc', 'You need to pay a £50 deposit to reserve the room.', array['pay a deposit', 'refundable deposit']::text[], 1),
('itinerary', '/aɪˈtɪnərəri/', 'a planned route or journey', 'lịch trình', 'Our itinerary includes three days in Edinburgh.', array['detailed itinerary', 'plan an itinerary']::text[], 1),
('adjacent', '/əˈdʒeɪsnt/', 'next to or near something', 'liền kề', 'The café is adjacent to the main entrance.', array['adjacent to', 'adjacent room']::text[], 2),
('facility', '/fəˈsɪləti/', 'a building or equipment provided for a purpose', 'cơ sở vật chất', 'The sports facilities are open until 10 pm.', array['sports facilities', 'leisure facility']::text[], 2),
('methodology', '/ˌmeθəˈdɒlədʒi/', 'a system of methods used in research', 'phương pháp luận', 'We need to explain our methodology in the report.', array['research methodology', 'adopt a methodology']::text[], 3),
('feasible', '/ˈfiːzəbl/', 'possible and practical to do', 'khả thi', 'Is it feasible to finish the survey by Friday?', array['economically feasible', 'technically feasible']::text[], 3),
('habitat', '/ˈhæbɪtæt/', 'the natural home of an animal or plant', 'môi trường sống', 'Deforestation is destroying the orangutan’s habitat.', array['natural habitat', 'habitat loss']::text[], 4),
('phenomenon', '/fəˈnɒmɪnən/', 'a fact or event that can be observed', 'hiện tượng', 'Migration is a well-documented natural phenomenon.', array['natural phenomenon', 'global phenomenon']::text[], 4),
('substantial', '/səbˈstænʃl/', 'large in amount or importance', 'đáng kể', 'There has been a substantial increase in sales.', array['substantial increase', 'substantial evidence']::text[], 5),
('undermine', '/ˌʌndəˈmaɪn/', 'to make something weaker gradually', 'làm suy yếu', 'Lack of sleep can undermine your concentration.', array['undermine confidence', 'seriously undermine']::text[], 5);
